        let row: ToonNode = toon_at(rows, r);
        if !toon_is_arr(row) {
            fx { println("row ", r, " skipped (", toon_type(row), ")"); }
            continue;
        }
        if toon_len(row) != width {
            fx { println("row ", r, " ragged (", toon_len(row), " cells)"); }
