fn reversed(s: Text) -> Text {
    let ms: MStream = mstreamcreate();
    loop i in string_len(s) - 1..-1 step -1 {
        mstreamappendbyte(ms, ord(s[i]));
    }
    let r: Text = mstreambuffer(ms);
    mstreamfree(ms);
    ret r;
}

