// 315_par_per_branch_records
// Concepts: par block with direct calls, one record per branch (never share a
// record across branches), combining branch results after the par block
// expect: low = 1225 over 50
// expect: high = 3725 over 50
// expect: grand = 4950

type Stats {
    total: Int = 0;
    count: Int = 0;
}

fn sum_range(stats: Stats, lo: Int, hi: Int) -> Void {
    loop i in lo..hi { stats.total = stats.total + i; stats.count = stats.count + 1; }
    ret;
}

fn main() -> Void {
    let low: Stats = new Stats();
    let high: Stats = new Stats();

    par {
        sum_range(low, 0, 50);
        sum_range(high, 50, 100);
    }

    fx {
        println("low = ", low.total, " over ", low.count);
        println("high = ", high.total, " over ", high.count);
        println("grand = ", low.total + high.total);
    }
    ret;
}

@pure
fn fib(n: Int) -> Int {
    if n <= 1 { ret n; }
    let a: Int = 0;
    let b: Int = 1;
    loop i in 2..n {
        let temp: Int = a + b;
        a = b;
        b = temp;
    }
    ret b;
}

@pure
fn make_row(n: Int, val: Int) -> Text {
    let spaces: Int = n - val;
    let row: Text = "";
    loop i in 0..spaces { row = row + " "; }
    row = row + "*";
    ret row;
}

fn main() -> Void {
    let limit: Int = 10;
    fx {
        println("Fibonacci Spiral (first 10):");
        println("----------------------------");
    }
    loop i in 0..limit {
        let val: Int = fib(i);
        let line: Text = make_row(limit, val);
        fx { println(line); }
    }
    fx { println("----------------------------"); println("Done."); }
    ret;
}

@pure
fn classify_status(code: Int) -> Text {
    if code == 200 { ret "OK"; }
    if code >= 400 { ret "ERROR"; }
    ret "PENDING";
}

fn main() -> Void {
    if !has_toon() { fx { println("yyjson unavailable"); } ret; }

    let json_payload: Text = "{\"users\":[{\"id\":1,\"meta\":{\"status\":200,\"details\":{\"code\":\"A\"}}},{\"id\":2,\"meta\":{\"status\":404}}]}";
    let doc: ToonDoc = toon_parse(json_payload);
    let root: ToonNode = toon_root(doc);
    let users: ToonNode = toon_key(root, "users");
    let count: Int = 0;

    fx { println("Processing Users:"); }

    loop i in 0..toon_len(users) {
        let user: ToonNode = toon_at(users, i);
        let id: Int = toon_get_int_or(user, "id", 0);
        let status: Text = "UNKNOWN";

        if toon_has_key(user, "meta") {
            let meta: ToonNode = toon_key(user, "meta");
            let code: Int = toon_get_int_or(meta, "status", 0);
            status = classify_status(code);

            if toon_has_key(meta, "details") {
                let details: ToonNode = toon_key(meta, "details");
                let detail_code: Text = toon_get_text_or(details, "code", "N/A");
                fx { println("  ID: ", id, " | Status: ", status, " | Detail: ", detail_code); }
            } else {
                fx { println("  ID: ", id, " | Status: ", status, " | No details"); }
            }
        } else {
            fx { println("  ID: ", id, " | No metadata"); }
        }
        count = count + 1;
    }

    fx { println("Total processed: ", count); }

    toon_close(doc);
    ret;
}

type Tally {
    total: Int;
    label: Text;
}

fn worker(out: Tally, n: Int) -> Void {
    let sum: Int = 0;
    loop i in 0..n { sum = sum + i; }
    out.total = sum;
    ret;
}

fn main() -> Void {
    let task_a: Tally = new Tally { label: "Alpha" };
    let task_b: Tally = new Tally { label: "Beta" };
    let task_c: Tally = new Tally { label: "Gamma" };

    fx { println("Starting concurrent tasks..."); }

    par {
        worker(task_a, 100);
        worker(task_b, 200);
        worker(task_c, 300);
    }

    // Branches run in no fixed order, so report only after the par block joins.
    fx {
        println("Worker ", task_a.label, " finished sum: ", task_a.total);
        println("Worker ", task_b.label, " finished sum: ", task_b.total);
        println("Worker ", task_c.label, " finished sum: ", task_c.total);
        println("All tasks complete.");
        println("Alpha total: ", task_a.total);
        println("Beta total: ", task_b.total);
        println("Gamma total: ", task_c.total);
        println("Grand Total: ", task_a.total + task_b.total + task_c.total);
    }

    ret;
}

@pure
fn compute_row(deg: Int) -> (Real, Real, Real) {
    let rad: Real = deg * 3.14159265359 / 180.0;
    let s: Real = sin(rad);
    let c: Real = cos(rad);
    let t: Real = tan(rad);
    ret (s, c, t);
}

fn main() -> Void {
    fx { println("Angle | Sin | Cos | Tan"); println("------------------------"); }

    let angle: Int = 0;
    loop angle < 90 {
        let (s, c, t) = compute_row(angle);
        fx { println(angle, " | ", s:0:4, " | ", c:0:4, " | ", t:0:4); }
        angle = angle + 15;
    }

    fx {
        println("------------------------");
        println("Natural Log of 2.0: ", ln(2.0):0:6);
        println("Square root of 2.0: ", sqrt(2.0):0:6);
    }

    ret;
}

fn bubble_sort(xs: Int[]) -> Int[] {
    let result: Int[] = xs;
    let n: Int = length(result);
    let swapped: Bool = true;
    loop while swapped {
        swapped = false;
        loop i in 0..n - 1 {
            if result[i] > result[i + 1] {
                let temp: Int = result[i];
                result[i] = result[i + 1];
                result[i + 1] = temp;
                swapped = true;
            }
        }
    }
    ret result;
}

fn main() -> Void {
    let data: Int[] = [64, 34, 25, 12, 22, 11, 90];

    fx {
        println("Original: ");
        loop i in 0..length(data) { println(data[i], " "); }
        println("");
    }

    data = bubble_sort(data);

    fx {
        println("Sorted:   ");
        loop i in 0..length(data) { println(data[i], " "); }
        println("");
    }

    ret;
}

@pure
