type Board {
    cells: Text[];

    fn get(r: Int, c: Int) -> Text {
        ret self.cells[r * 3 + c];
    }

    fn place(r: Int, c: Int, mark: Text) -> Void {
        self.cells[r * 3 + c] = mark;
        ret;
    }

    fn checkWin(mark: Text) -> Bool {
        loop r in 0..3 {
            if self.get(r, 0) == mark && self.get(r, 1) == mark && self.get(r, 2) == mark {
                ret true;
            }
        }
        loop c in 0..3 {
            if self.get(0, c) == mark && self.get(1, c) == mark && self.get(2, c) == mark {
                ret true;
            }
        }
        if self.get(0, 0) == mark && self.get(1, 1) == mark && self.get(2, 2) == mark {
            ret true;
        }
        if self.get(0, 2) == mark && self.get(1, 1) == mark && self.get(2, 0) == mark {
            ret true;
        }
        ret false;
    }

    fn isFull() -> Bool {
        loop i in 0..9 { if self.cells[i] == " " { ret false; } }
        ret true;
    }

    fn display() -> Void {
        loop r in 0..3 {
            fx { println(" ", self.get(r, 0), " | ", self.get(r, 1), " | ", self.get(r, 2)); }
            if r < 2 { fx { println("-----------"); } }
        }
        ret;
    }
}

fn makeBoard() -> Board {
    let empty: Text[] = [];
    loop i in 0..9 { empty = empty + [" "]; }
    ret new Board { cells: empty };
}

fn main() -> Void {
    let board: Board = makeBoard();
    let current: Text = "X";
    let gameOver: Bool = false;

    fx { println("Tic-Tac-Toe: X goes first"); }

    loop !gameOver {
        board.display();

        let placed: Bool = false;
        loop r in 0..3 {
            if placed { break; }
            loop c in 0..3 {
                if placed { break; }
                if board.get(r, c) == " " { board.place(r, c, current); placed = true; }
            }
        }

        if board.checkWin(current) {
            board.display();
            fx { println(current, " wins!"); }
            gameOver = true;
        } else if board.isFull() {
            board.display();
            fx { println("Draw!"); }
            gameOver = true;
        } else {
            if current == "X" {
                current = "O";
            } else {
                current = "X";
            }
        }
    }
    ret;
}

type Node {
    value: Int;
    next: Node;
}

fn makeNode(val: Int) -> Node {
    ret new Node { value: val, next: nil };
}

type LinkedList {
    head: Node;

    fn prepend(val: Int) -> Void {
        let node: Node = makeNode(val);
        node.next = self.head;
        self.head = node;
        ret;
    }

    fn append(val: Int) -> Void {
        let node: Node = makeNode(val);
        if self.head == nil { self.head = node; ret; }
        let current: Node = self.head;
        loop current.next != nil { current = current.next; }
        current.next = node;
        ret;
    }

    fn size() -> Int {
        let count: Int = 0;
        let current: Node = self.head;
        loop current != nil { count = count + 1; current = current.next; }
        ret count;
    }

    fn toText() -> Text {
        let result: Text = "[";
        let current: Node = self.head;
        let first: Bool = true;
        loop current != nil {
            if !first { result = result + ", "; }
            result = result + itoa(current.value);
            first = false;
            current = current.next;
        }
        ret result + "]";
    }
}

fn main() -> Void {
    let list: LinkedList = new LinkedList { head: nil };

    list.append(10);
    list.append(20);
    list.append(30);
    list.prepend(5);
    list.prepend(1);

    fx { println("List: ", list.toText()); println("Length: ", list.size()); }
    ret;
}

type Stack {
    items: Int[];

    fn push(val: Int) -> Void {
        self.items = self.items + [val];
        ret;
    }

    fn pop() -> Int {
        let top: Int = self.items[length(self.items) - 1];
        let newItems: Int[] = [];
        loop i in 0..length(self.items) - 1 { newItems = newItems + [self.items[i]]; }
        self.items = newItems;
        ret top;
    }

    fn peek() -> Int {
        ret self.items[length(self.items) - 1];
    }

    fn size() -> Int {
        ret length(self.items);
    }
}

@pure
fn isOp(ch: Text) -> Bool {
    if ch == "+" { ret true; }
    if ch == "-" { ret true; }
    if ch == "*" { ret true; }
    if ch == "/" { ret true; }
    ret false;
}

fn evalRPN(tokens: Text[]) -> Int {
    let stack: Stack = new Stack { items: [] };

    loop i in 0..length(tokens) {
        let tok: Text = tokens[i];
        if isOp(tok) {
            let b: Int = stack.pop();
            let a: Int = stack.pop();
            let result: Int = 0;
            if tok == "+" { result = a + b; }
            if tok == "-" { result = a - b; }
            if tok == "*" { result = a * b; }
            if tok == "/" { result = a / b; }
            stack.push(result);
        } else {
            stack.push(parse_int(tok));
        }
    }
    ret stack.pop();
}

fn main() -> Void {
    let expr1: Text[] = ["2", "3", "+", "4", "*"];
    let expr2: Text[] = ["5", "1", "2", "+", "4", "*", "+", "3", "-"];

    fx {
        println("Expression: 2 3 + 4 * => ", evalRPN(expr1));
        println("Expression: 5 1 2 + 4 * + 3 - => ", evalRPN(expr2));
    }
    ret;
}

