    let primes: Int[] = generate_primes(limit);
    fx {
        print("Primes up to ", limit, ": ");
        loop i in 0..length(primes) { print(primes[i], " "); }
        println("");
    }
    ret;
}

type Json {
    kind: Text;  // "object", "array", "string", "number", "bool", "null"
    value: Text;
    children: Json[];
}

@pure
fn is_digit(ch: Text) -> Bool {
    let code: Int = ord(ch);
    ret code >= 48 && code <= 57;
}

@pure
fn is_number(text: Text) -> Bool {
    loop i in 0..string_len(text) {
        let c: Text = copy(text, i, 1);
        if !is_digit(c) && c != "." && c != "-" { ret false; }
    }
    ret true;
}

fn parse_json(text: Text) -> Json {
    if text == "null" { ret new Json { kind: "null", value: "null", children: [] }; }
    if text == "true" || text == "false" {
        ret new Json { kind: "bool", value: text, children: [] };
    }
    if is_number(text) { ret new Json { kind: "number", value: text, children: [] }; }
    let len: Int = string_len(text);
    if len >= 2 && copy(text, 0, 1) == "\"" && copy(text, len - 1, 1) == "\"" {
        ret new Json { kind: "string", value: copy(text, 1, len - 2), children: [] };
    }
    ret new Json { kind: "unknown", value: "", children: [] };
}

fn main() -> Void {
    let json_text: Text = "\"Alice\"";
    let json: Json = parse_json(json_text);
    fx {
        println("Parsed JSON kind: ", json.kind);
        println("Parsed JSON value: ", json.value);
    }
    ret;
}

// Grayscale conversion over an in-memory Image. Aether's real file I/O
// (assign/reset/rewrite/readln/writeln) is text-line-oriented, not
// byte-level, so there is no way to parse a binary BMP file from Aether
// source -- this demonstrates the pixel-transform logic on synthetic data
// instead of pretending to load/save a real image file.
type Pixel {
    r: Int;
    g: Int;
    b: Int;
}

type Image {
    width: Int;
    height: Int;
    pixels: Pixel[];
}

fn make_test_image(width: Int, height: Int) -> Image {
    let pixels: Pixel[] = [];
    loop i in 0..width * height {
        pixels = pixels + [new Pixel { r: (i * 37) % 256, g: (i * 59) % 256, b: (i * 83) % 256 }];
    }
    ret new Image { width: width, height: height, pixels: pixels };
}

fn grayscale(image: Image) -> Image {
    let gray_pixels: Pixel[] = [];
    loop i in 0..length(image.pixels) {
        let p: Pixel = image.pixels[i];
        let gray: Int = int(0.299 * real(p.r) + 0.587 * real(p.g) + 0.114 * real(p.b));
        gray_pixels = gray_pixels + [new Pixel { r: gray, g: gray, b: gray }];
    }
    ret new Image { width: image.width, height: image.height, pixels: gray_pixels };
}

fn main() -> Void {
    let image: Image = make_test_image(2, 2);
    let gray: Image = grayscale(image);
    fx {
        loop i in 0..length(gray.pixels) {
            let p: Pixel = gray.pixels[i];
            println("pixel ", i, ": r=", p.r, " g=", p.g, " b=", p.b);
        }
    }
    ret;
}

type DB {
    data: Text[];
}

fn open_store(filename: Text) -> DB {
    let data: Text[] = [];
    fx {
        if fileexists(filename) {
            let f: File;
            assign(f, filename);
            reset(f);
            loop {
                if eof(f) { break; }
                let line: Text;
                readln(f, line);
                if string_len(line) > 0 { data = data + [line]; }
            }
            close(f);
        }
    }
    ret new DB { data: data };
}

fn put_entry(db: DB, key: Text, value: Text) -> Void {
    let index: Int = -1;
    let i: Int = 0;
    loop i < length(db.data) { if db.data[i] == key { index = i; break; } i = i + 2; }
    if index != -1 {
        db.data[index + 1] = value;
    } else {
        db.data = db.data + [key];
        db.data = db.data + [value];
    }
    ret;
}

fn get_entry(db: DB, key: Text) -> Text {
    let i: Int = 0;
    loop i < length(db.data) { if db.data[i] == key { ret db.data[i + 1]; } i = i + 2; }
    ret "";
}

fn save_store(db: DB, filename: Text) -> Void {
    fx {
        let f: File;
        assign(f, filename);
        rewrite(f);
        loop i in 0..length(db.data) { writeln(f, db.data[i]); }
        close(f);
    }
    ret;
}

fn main() -> Void {
    let db: DB = open_store("/tmp/aether_db_demo.txt");
    put_entry(db, "name", "Alice");
    put_entry(db, "age", "30");
    fx {
        println("Name: ", get_entry(db, "name"));
        println("Age: ", get_entry(db, "age"));
    }
    save_store(db, "/tmp/aether_db_demo.txt");
    ret;
}

@pure
fn vigenere_encrypt(text: Text, key: Text) -> Text {
    let result: Text = "";
    let key_len: Int = string_len(key);
    loop i in 0..string_len(text) {
        let c: Int = ord(copy(text, i, 1));
        let k: Int = ord(copy(key, i % key_len, 1));
        let encrypted: Int = (c + k - 2 * 97) % 26 + 97;
        result = result + chr(encrypted);
    }
    ret result;
}

@pure
fn vigenere_decrypt(text: Text, key: Text) -> Text {
    let result: Text = "";
    let key_len: Int = string_len(key);
    loop i in 0..string_len(text) {
        let c: Int = ord(copy(text, i, 1));
        let k: Int = ord(copy(key, i % key_len, 1));
        let decrypted: Int = (c - k + 26) % 26 + 97;
        result = result + chr(decrypted);
    }
    ret result;
}

fn main() -> Void {
    let plaintext: Text = "hello";
    let key: Text = "secret";
    let ciphertext: Text = vigenere_encrypt(plaintext, key);
    let decrypted: Text = vigenere_decrypt(ciphertext, key);
    fx {
        println("Original: ", plaintext);
        println("Encrypted: ", ciphertext);
        println("Decrypted: ", decrypted);
    }
    ret;
}

type Neuron {
    weights: Real[];
    bias: Real;
}

type Layer {
    neurons: Neuron[];
}

type Network {
    layers: Layer[];
}

@pure
fn sigmoid(x: Real) -> Real {
    ret 1.0 / (1.0 + exp(-x));
}

fn forward(network: Network, input: Real[]) -> Real[] {
    let output: Real[] = input;
    loop l in 0..length(network.layers) {
        let layer: Layer = network.layers[l];
        let new_output: Real[] = [];
        loop n in 0..length(layer.neurons) {
            let neuron: Neuron = layer.neurons[n];
            let sum: Real = 0.0;
            loop i in 0..length(output) { sum = sum + output[i] * neuron.weights[i]; }
            sum = sum + neuron.bias;
            new_output = new_output + [sigmoid(sum)];
        }
        output = new_output;
    }
    ret output;
}

fn main() -> Void {
    let network: Network = new Network { layers: [
        new Layer { neurons: [
            new Neuron { weights: [0.5, -0.5], bias: 0.1 },
            new Neuron { weights: [0.3, 0.7], bias: -0.2 }
        ]}
    ]};
    let input: Real[] = [1.0, 2.0];
    let output: Real[] = forward(network, input);
    fx {
        print("Output: ");
        loop i in 0..length(output) { print(output[i]:0:4, " "); }
        println("");
    }
    ret;
}

// A minimal test runner. Aether has no function values (FUNC-001) -- no
// closures, no fn-typed fields -- so tests can't be stored as
// Test { fn: () -> Bool } records. Each test's boolean result is computed
// directly and reported through a small helper instead.
fn report(name: Text, passed: Bool, passCount: Int, failCount: Int) -> Int[] {
    fx {
        if passed {
            println("[PASS] ", name);
        } else {
            println("[FAIL] ", name);
        }
    }
    if passed { ret [passCount + 1, failCount]; }
    ret [passCount, failCount + 1];
}

fn main() -> Void {
    let passCount: Int = 0;
    let failCount: Int = 0;

    let r1: Int[] = report("2 + 2 = 4", 2 + 2 == 4, passCount, failCount);
    passCount = r1[0]; failCount = r1[1];

    let r2: Int[] = report("5 > 3", 5 > 3, passCount, failCount);
    passCount = r2[0]; failCount = r2[1];

    let r3: Int[] = report("Hello starts with H", copy("Hello", 0, 1) == "H", passCount, failCount);
    passCount = r3[0]; failCount = r3[1];

    fx { println("Passed: ", passCount, "/", passCount + failCount); }
    ret;
}

