fn bubble_sort(arr: Int[]) -> Int[] {
    let swapped: Bool = true;
    loop swapped {
        swapped = false;
        loop i in 0..(length(arr) - 1) {
            if arr[i] > arr[i + 1] {
                let temp: Int = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
                swapped = true;
            }
        }
    }
    ret arr;
}

fn main() -> Void {
    let nums: Int[] = [64, 34, 25, 12, 22, 11, 90];
    let sorted: Int[] = bubble_sort(nums);
    fx {
        print("Sorted array: ");
        loop i in 0..length(sorted) { print(sorted[i], " "); }
        println("");
    }
    ret;
}

fn prime_factors(n: Int) -> Int[] {
    let factors: Int[] = [];
    let divisor: Int = 2;
    let remaining: Int = n;
    loop remaining > 1 {
        if remaining % divisor == 0 {
            factors = factors + [divisor];
            remaining = remaining / divisor;
        } else {
            divisor = divisor + 1;
        }
    }
    ret factors;
}

fn main() -> Void {
    let num: Int = 315;
    let factors: Int[] = prime_factors(num);
    fx {
        print("Prime factors of ", num, ": ");
        loop i in 0..length(factors) { print(factors[i], " "); }
        println("");
    }
    ret;
}

fn is_armstrong(n: Int) -> Bool {
    let num_str: Text = int_to_text(n);
    let power: Int = string_len(num_str);
    let sum: Int = 0;
    loop i in 0..string_len(num_str) {
        let digit: Int = parse_int(copy(num_str, i, 1));
        sum = sum + pow(digit, power);
    }
    ret sum == n;
}

fn main() -> Void {
