    fx { println(num, " is armstrong: ", is_armstrong(num)); }
    ret;
}

fn find_lcm(a: Int, b: Int) -> Int {
    let greater: Int = if a > b { a } else { b };
    loop {
        if greater % a == 0 && greater % b == 0 { ret greater; }
        greater = greater + 1;
    }
}

