type KVStore {
    keys: Text[];
    values: Text[];

    fn init() -> Void {
        self.keys = [];
        self.values = [];
        ret;
    }

    fn put(key: Text, value: Text) -> Void {
        let found: Bool = false;
        loop i in 0..length(self.keys) {
            if self.keys[i] == key { self.values[i] = value; found = true; }
        }
        if !found { self.keys = self.keys + [key]; self.values = self.values + [value]; }
        ret;
    }

    fn get(key: Text) -> Text {
        loop i in 0..length(self.keys) { if self.keys[i] == key { ret self.values[i]; } }
        ret "";
    }

    fn save(path: Text) -> Bool {
        fx {
            let f: File;
            assign(f, path);
            rewrite(f);
            loop i in 0..length(self.keys) {
                writeln(f, self.keys[i] + "=" + self.values[i]);
            }
            close(f);
        }
        ret true;
    }

    fn load(path: Text) -> Bool {
        fx {
            let f: File;
            assign(f, path);
            reset(f);
            loop {
                if eof(f) { break; }
                let line: Text;
                readln(f, line);
                if string_len(line) > 0 {
                    let eqpos: Int = pos("=", line);
                    if eqpos >= 0 {
                        let k: Text = copy(line, 0, eqpos);
                        let v: Text = copy(line, eqpos + 1, string_len(line) - eqpos - 1);
                        self.put(k, v);
                    }
                }
            }
            close(f);
        }
        ret true;
    }
}

