fn clamp01(x: Real) -> Real {
    if x < 0.0 { ret 0.0; }
    if x > 1.0 { ret 1.0; }
    ret x;
}

fn split_csv_line(line: Text) -> Text[] {
    let parts: Text[] = [];
    let current: Text = "";
    let i: Int = 0;
    loop i < string_len(line) {
        let ch: Text = copy(line, i, 1);
        if ch == "," {
            parts = parts + [current];
            current = "";
        } else {
            current = current + ch;
        }
        i = i + 1;
    }
    parts = parts + [current];
    ret parts;
}

type Stats {
    seen: Int = 0;
    total: Real = 0.0;
    minValue: Real = 0.0;
    maxValue: Real = 0.0;
    initialized: Bool = false;

    fn observe(value: Real) -> Void {
        if !self.initialized {
            self.minValue = value;
            self.maxValue = value;
            self.initialized = true;
        } else {
            if value < self.minValue { self.minValue = value; }
            if value > self.maxValue { self.maxValue = value; }
        }
        self.seen = self.seen + 1;
        self.total = self.total + value;
        ret;
    }

    fn mean() -> Real {
        if self.seen == 0 { ret 0.0; }
        ret self.total / self.seen;
    }
}

