@pure
fn bitAt(k: Int) -> Int {
    let b: Int = 1;
    loop i in 0..k { b = b * 2; }
    ret b;
}

@pure
fn knapsack(weights: Int[], values: Int[], cap: Int) -> (Int, Int) {
    let items: Int = length(weights);
    let width: Int = cap + 1;
    let rows: Int = items + 1;
    let cells: Int = rows * width;
    let dp: Int[] = [];
    let mk: Int[] = [];
    loop i in 0..cells { dp = dp + [0]; mk = mk + [0]; }
    loop i in 1..rows {
        loop w in 0..width {
            let prev: Int = (i - 1) * width;
            let best: Int = dp[prev + w];
            let mask: Int = mk[prev + w];
            if weights[i - 1] <= w {
                let cand: Int = dp[prev + (w - weights[i - 1])] + values[i - 1];
                if cand > best {
                    best = cand;
                    mask = mk[prev + (w - weights[i - 1])] + bitAt(i - 1);
                }
            }
            dp[i * width + w] = best;
            mk[i * width + w] = mask;
        }
    }
    ret (dp[items * width + cap], mk[items * width + cap]);
}

fn main() -> Void {
    let weights: Int[] = [2, 3, 4, 5];
    let values: Int[] = [3, 4, 5, 6];
    let cap: Int = 5;
    let res = knapsack(weights, values, cap);
    fx {
        println("capacity = ", cap);
        println("best value = ", res.0);
        loop i in 0..length(weights) {
            if (res.1 & bitAt(i)) > 0 {
                println("take item ", i, " (w=", weights[i], ", v=", values[i], ")");
            }
        }
    }
    ret;
}

@pure
fn bfs8(walls: Int[], start: Int, goal: Int) -> Int {
    // 64 cells; row = idx >> 3, col = idx & 7
    let dist: Int[] = [];
    loop i in 0..64 { dist = dist + [-1]; }
    let queue: Int[] = [];
    queue = queue + [start];
    dist[start] = 0;
    let head: Int = 0;
    loop guard in 0..64 {
        if head < length(queue) {
            let cur: Int = queue[head];
            head = head + 1;
            let row: Int = cur >> 3;
            let col: Int = cur & 7;
            let next: Int = dist[cur] + 1;
            if row > 0 {
                let nb: Int = cur - 8;
                if walls[nb] == 0 && dist[nb] == -1 {
                    dist[nb] = next;
                    queue = queue + [nb];
                }
            }
            if row < 7 {
                let nb: Int = cur + 8;
                if walls[nb] == 0 && dist[nb] == -1 {
                    dist[nb] = next;
                    queue = queue + [nb];
                }
            }
            if col > 0 {
                let nb: Int = cur - 1;
                if walls[nb] == 0 && dist[nb] == -1 {
                    dist[nb] = next;
                    queue = queue + [nb];
                }
            }
            if col < 7 {
                let nb: Int = cur + 1;
                if walls[nb] == 0 && dist[nb] == -1 {
                    dist[nb] = next;
                    queue = queue + [nb];
                }
            }
        }
    }
    ret dist[goal];
}

fn main() -> Void {
    let walls: Int[] = [];
    loop i in 0..64 { walls = walls + [0]; }
    // vertical barrier in column 4, rows 0..6, with a gap at row 7
    loop r in 0..7 { walls[r * 8 + 4] = 1; }
    // extra rubble
    walls[9] = 1;
    walls[10] = 1;
    walls[11] = 1;
    walls[50] = 1;
    walls[51] = 1;

    let d: Int = bfs8(walls, 0, 63);

    fx {
        loop r in 0..8 {
            let line: Text = "";
            loop c in 0..8 {
                if walls[r * 8 + c] == 1 {
                    line = line + "#";
                } else {
                    line = line + ".";
                }
            }
            println(line);
        }
        println("shortest path (0,0) -> (7,7) = ", d);
    }
    ret;
}

